$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT s.*,u.full_name FROM sales s JOIN users u ON u.id=s.user_id WHERE s.id=? AND s.branch_id=?');$s->execute([$id,$branchId]);$sale=$s->fetch();if(!$sale){http_response_code(404);exit('Receipt not found');}
