?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receipt <?=e($sale['invoice_no'])?></title><link rel="stylesheet" href="assets/style.css"></head><body><main class="container" style="max-width:620px"><section class="panel"><div class="print-only"></div><center><h2>DELTA DRUG STORE</h2><div>Sales Receipt</div><small><?=e($sale['invoice_no'])?></small></center><hr><p>Date: <?=e($sale['created_at'])?><br>Cashier: <?=e($sale['full_name'])?><br>Payment: <?=e($sale['payment_method'])?></p><table><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['name'])?></td><td><?=e($i['qty'].' '.$i['unit'])?></td><td><?=money($i['unit_price'])?></td><td><?=money($i['line_total'])?></td></tr><?php endforeach?></table><p class="right">Subtotal: <?=money($sale['subtotal'])?><br>Discount: <?=money($sale['discount'])?><br><strong class="total">TOTAL: <?=money($sale['total'])?></strong></p><center>Thank you for shopping with us.</center></section><div class="actions no-print"><button onclick="window.print()">Print receipt</button><a class="btn secondary" href="sales.php">Back to sales</a></div></main></body></html>
